-- Read-only catalog export. Deliberately excludes user rows, passwords and credentials.
-- No SQL files are read by the server; the caller receives metadata only.
with namespaces as (select oid,nspname from pg_namespace where nspname in ('public','private','auth','storage')),
tables as(select c.oid,n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity,c.relacl,c.relowner from pg_class c join namespaces n on n.oid=c.relnamespace where c.relkind in ('r','p')),
funcs as(select p.*,n.nspname from pg_proc p join namespaces n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where p.prokind='f' and l.lanname in ('sql','plpgsql'))
select jsonb_build_object(
 'formatVersion',1,
 'capturedAt',now(),
 'enums',coalesce((select jsonb_agg(format('create type %I.%I as enum (%s);',n.nspname,t.typname,v.labels)) from pg_type t join namespaces n on n.oid=t.typnamespace cross join lateral(select string_agg(quote_literal(e.enumlabel),',' order by e.enumsortorder)labels from pg_enum e where e.enumtypid=t.oid)v where t.typtype='e'),'[]'::jsonb),
 'sequences',coalesce((select jsonb_agg(format('create sequence %I.%I;',n.nspname,c.relname)) from pg_class c join namespaces n on n.oid=c.relnamespace where c.relkind='S' and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='i')),'[]'::jsonb),
 'tables',coalesce((select jsonb_agg(jsonb_build_object('name',format('%I.%I',t.nspname,t.relname),'sql',format('create table %I.%I (%s);',t.nspname,t.relname,cols.sql),'rls',t.relrowsecurity,'forceRls',t.relforcerowsecurity)) from tables t cross join lateral(select string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attidentity<>'' then ' generated by default as identity' when a.attgenerated<>'' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),',' order by a.attnum)sql from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=t.oid and a.attnum>0 and not a.attisdropped)cols),'[]'::jsonb),
 'constraints',coalesce((select jsonb_agg(jsonb_build_object('kind',c.contype,'sql',format('alter table %I.%I add constraint %I %s;',t.nspname,t.relname,c.conname,pg_get_constraintdef(c.oid,true))) order by case c.contype when 'p' then 1 when 'u' then 2 when 'c' then 3 else 4 end) from pg_constraint c join tables t on t.oid=c.conrelid where c.contype in ('p','u','c','f','x')),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('name',p.oid::regprocedure::text,'sql',pg_get_functiondef(p.oid))) from funcs p),'[]'::jsonb),
 'views',coalesce((select jsonb_agg(format('create %sview %I.%I as %s%s;',case when c.relkind='m' then 'materialized ' else '' end,n.nspname,c.relname,rtrim(pg_get_viewdef(c.oid,true),';'),case when c.relkind='m' then ' with no data' else '' end)) from pg_class c join namespaces n on n.oid=c.relnamespace where c.relkind in ('v','m')),'[]'::jsonb),
 'indexes',coalesce((select jsonb_agg(pg_get_indexdef(i.indexrelid)||';') from pg_index i join tables t on t.oid=i.indrelid where not exists(select 1 from pg_constraint c where c.conindid=i.indexrelid)),'[]'::jsonb),
 'triggers',coalesce((select jsonb_agg(pg_get_triggerdef(g.oid,true)||';') from pg_trigger g join tables t on t.oid=g.tgrelid where not g.tgisinternal),'[]'::jsonb),
 'policies',coalesce((select jsonb_agg(format('create policy %I on %I.%I as %s for %s to %s%s%s;',p.polname,t.nspname,t.relname,case when p.polpermissive then 'permissive' else 'restrictive' end,case p.polcmd when 'r' then 'select' when 'a' then 'insert' when 'w' then 'update' when 'd' then 'delete' else 'all' end,roles.sql,case when p.polqual is not null then ' using ('||pg_get_expr(p.polqual,p.polrelid)||')' else '' end,case when p.polwithcheck is not null then ' with check ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' else '' end)) from pg_policy p join tables t on t.oid=p.polrelid cross join lateral(select string_agg(case when r=0 then 'public' else quote_ident(pg_get_userbyid(r)) end,',')sql from unnest(p.polroles)r)roles),'[]'::jsonb),
 'roles',coalesce((select jsonb_agg(jsonb_build_object('name',rolname,'bypassRls',rolbypassrls)) from pg_roles where rolname not like 'pg\_%' and rolname<>'postgres'),'[]'::jsonb),
 'grants',coalesce((select jsonb_agg(sql) from (
  select format('grant %s on table %I.%I to %s;',a.privilege_type,t.nspname,t.relname,case a.grantee when 0 then 'public' else quote_ident(pg_get_userbyid(a.grantee))end)sql from tables t cross join lateral aclexplode(t.relacl)a
  union all select format('grant %s(%I) on table %I.%I to %s;',g.privilege_type,a.attname,t.nspname,t.relname,case g.grantee when 0 then 'public' else quote_ident(pg_get_userbyid(g.grantee))end) from tables t join pg_attribute a on a.attrelid=t.oid and a.attnum>0 cross join lateral aclexplode(a.attacl)g
  union all select format('revoke all on function %s from public,anon,authenticated,service_role;',p.oid::regprocedure::text) from funcs p
  union all select format('grant %s on function %s to %s;',a.privilege_type,p.oid::regprocedure::text,case a.grantee when 0 then 'public' else quote_ident(pg_get_userbyid(a.grantee))end) from funcs p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a
 )g),'[]'::jsonb),
 'settings',coalesce((select jsonb_agg(jsonb_build_object('key',setting_key,'version',version,'value',value,'effectiveAt',effective_at)) from public.business_setting_versions where setting_key='selling_rules'),'[]'::jsonb)
) as snapshot;
